// Van Nguyen created a List of languages
const languages = [

    {name:"English",code:"en",flag:"us"},
    {name:"Spanish",code:"es",flag:"es"},
    {name:"Portuguese",code:"pt",flag:"pt"},
    {name:"Chinese (Simplified)",code:"zh-CN",flag:"cn"},
    {name:"Chinese (Traditional)",code:"zh-TW",flag:"tw"},
    {name:"Haitian Creole",code:"ht",flag:"ht"},
    {name:"Vietnamese",code:"vi",flag:"vn"},
    {name:"Russian",code:"ru",flag:"ru"},
    {name:"Arabic",code:"ar",flag:"sa"},
    {name:"French",code:"fr",flag:"fr"}

   ];

// Build 4‑column grid menu
function buildMenu(){
    const menu = document.getElementById("translate_menu");
    menu.innerHTML = "";
    languages.forEach(lang => {
        const a = document.createElement("a");
        a.href = "#";
        /* a.innerHTML = '<img class="flag" src="https://flagcdn.com/w20/'+lang.flag+'.png"> '+lang.name; */
       // just a simple bullet point instead of flag icon:
       a.innerHTML = '• ' + lang.name;  // simple bullet point
        a.onclick = function(e){
            e.preventDefault();
            doGTranslate('en|'+lang.code);
            menu.style.display="none";
        };
        menu.appendChild(a);
    });
}

// Google Translate init
function googleTranslateElementInit(){
    new google.translate.TranslateElement({pageLanguage:'en'}, 'google_translate_element');
}

// Change language
function doGTranslate(lang_pair){
    var lang=lang_pair.split('|')[1];
    var select=document.querySelector(".goog-te-combo");
    if(select){
        select.value=lang;
        select.dispatchEvent(new Event("change"));
    }
}

// Toggle menu
document.getElementById("translate_button").addEventListener("click",function(){
    const menu = document.getElementById("translate_menu");
    menu.style.display = (menu.style.display==="block")?"none":"block";
});

// Close when clicking outside
document.addEventListener("click",function(e){
    const container = document.getElementById("translate_container");
    const menu = document.getElementById("translate_menu");
    if(!container.contains(e.target) && menu.style.display==="block"){
        menu.style.display="none";
    }
});

buildMenu();




 
	 

	 

	   

	   

			   


	 
 
 
 	 
				                

		 				
	 

	 	
 
	 
	 

