#translate_container{
    position: relative!important; /* container is reference for absolute menu */
    display: inline-block!important;
}

/* Button style */
#translate_button{
    background:#2c7be5;
    color:white;
    border:none;
    padding:6px 10px;
    font-size:14px;
    border-radius:4px;
    cursor:pointer;
}

/* Dropdown menu floating above button */
#translate_menu{
    display:none;
    position:absolute!important; /* absolute relative to container */
    bottom: 100%;       /* place menu above button */
    left:0;
    margin-bottom:4px;  /* small gap above button */
    background:white;
    border:1px solid #ccc;
    max-height:260px;
    overflow-y:auto;
    width:200px;
    box-shadow:0 4px 10px rgba(0,0,0,0.25);
    z-index:9999!important;       /* high z-index to float above other content */
}

#translate_menu a{
    display:flex!important;
    align-items:center!important;
    padding:6px 10px;
    text-decoration:none;
    color:#333;
    font-size:13px;
}

#translate_menu a:hover{
    background:#f0f0f0;
}

.flag{
    width:18px;
    margin-right:8px;
}

/* Hide Google default widget */
.goog-te-gadget{
    display:none !important;
}


